  const disMetin = () => { const s = disSuz(); return s.bas || s.bit ? `${s.bas ? s.bas.split('-').reverse().join('.') : '…'} – ${s.bit ? s.bit.split('-').reverse().join('.') : '…'}` : 'tüm tarihler'; };
  /** fark faturasının kaynağı: Tahsilat (ödeme vadeden sonra alındı, ör. çek vadesi) · Ay Sonu / Robot (vadesi geçtiği için) · Elle (Şimdi Kes) · Kur Farkı */
