    if (!c) { o.innerHTML = '<span class="text-muted">Cari seçince bakiye, son ödeme / yükleme, gecikme ve açık faturalar burada görünür.</span>'; i.style.setProperty('display', 'none', 'important'); return; }
    const b = BILGI || {};
    // 19 Kas 2026 (kullanıcı: "üst kısım alt satıra geçmiş; bu sayfada bulabileceğim bilgileri kaldır"): Açık Faturalar (tablo), Son 12 Ay ve Vade · Temsilci (vade şartı dinamik vade etiketinde) çıkarıldı
