  const satirlarIstek = () => SAT.map((s, i) => ({ sira: i + 1, yontem: s.yontem, tarih: s.tarih, belgeNo: s.belgeNo, banka: s.banka, pb: s.pb, kur: s.kur, kurElle: s.kurElle, tutar: s.tutar, not: s.not }));
