  // ============================================================
  // ADAT (19 Kas 2026, kullanıcı: "adat raporunda olanlar Yeni Tahsilat sayfasına da gelsin; fatura gün hesaplaması + adat hesaplaması"): Adat Hesaplama (adat.js) kurallarıyla
  //   gün = ödeme − vade (kapanmayanda bugün − vade), adat VF = kapanan × aylık oran × gün ÷ 3000 (eksi = lehte), aylık dağılım vade ayına göre, fazla ödeme avans.
  //   Kapanış satırları sunucunun FIFO dağıtımından (ON.dagitim) gelir; "Fatura VF" = kesilecek fatura matrahı (tolerans / önceki kesim düşülmüş), "Adat VF" bilgi amaçlı ve oranı değiştirilebilir.
  // ============================================================
  // ---- fatura detay penceresi (19 Kas 2026): Belge No → /Tahsilat/FaturaDetay (iframe); Esc / X kapatır
  function faturaAc(kod, no) {
    const p = $('#thFatPen'); if (!p) { window.open(`/Tahsilat/FaturaDetay?kod=${encodeURIComponent(kod)}&no=${encodeURIComponent(no)}`, '_blank'); return; }
    const url = `/Tahsilat/FaturaDetay?kod=${encodeURIComponent(kod)}&no=${encodeURIComponent(no)}`; const c = V.cariler.find(x => x.kod === kod);
    $('#thFatPenAd').textContent = `${no} · ${kod} ${c ? c.kisaAd : ''} · Fatura İncelemesi`; $('#thFatPenAc').href = url; $('#thFatPenIframe').src = url; p.hidden = false;
  }
  function faturaKapat() { const p = $('#thFatPen'); if (!p || p.hidden) return; p.hidden = true; $('#thFatPenIframe').src = 'about:blank'; }
  // 19 Kas 2026 gece (kullanıcı: "Açık Faturalar'da fatura incelemesi açılmıyor"): pencere #th panelinin İÇİNDEYDİ — başka sekme açıkken panel display:none olduğundan pencere görünmüyordu; rapor köküne (#tk) taşınır, kapatma kendi üstünde dinlenir
  { const p0 = $('#thFatPen'), tk0 = document.getElementById('tk'); if (p0 && tk0 && p0.closest('.na-panel')) { tk0.appendChild(p0); p0.addEventListener('click', e => { if (e.target.closest('#thFatPenKapat') || e.target === p0) faturaKapat(); }); } }
  kok.addEventListener('click', e => { const a = e.target.closest('[data-fatura]'); if (a) { e.preventDefault(); e.stopPropagation(); faturaAc(a.dataset.kod || ($('#thCari') || {}).value, a.dataset.fatura); return; } if (e.target.closest('#thFatPenKapat')) faturaKapat(); else if (e.target.id === 'thFatPen') faturaKapat(); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') faturaKapat(); });
  window.addEventListener('thFaturaAc', e => { const d = e.detail || {}; if (d.kod && d.no) { if (e.cancelable) e.preventDefault(); faturaAc(d.kod, d.no); } });   // rapor sekmelerinden (tahsilat-takip.js, adat.js) belge tıklanınca; preventDefault = "burada açıldı"
